#if DEBUG || BETA
  import Foundation
  import XCTest
  @testable import financeplan

  /// The expected values come from `vig-motion.fixtures.json`, a byte copy of
  /// `norviq-web-v2/design/vig-motion.fixtures.json` (generated by
  /// `scripts/brand/vig_motion_fixtures.py`). The web `src/lib/vig-motion.test.ts` loads the same
  /// file, so the web and iOS Vig move alike.
  @MainActor
  final class VigMotionTests: XCTestCase {
    private struct Fixtures: Decodable {
      struct EaseCase: Decodable { let easing: String; let u: Double; let expect: Double }
      struct EntranceExpect: Decodable { let opacity: Double; let rise: Double; let yawDegrees: Double }
      struct EntranceCase: Decodable { let t: Double; let expect: EntranceExpect }
      struct SwayCase: Decodable { let t: Double; let expect: Double }
      struct TiltExpect: Decodable { let yawDegrees: Double; let pitchDegrees: Double }
      struct PointerCase: Decodable { let x: Double; let y: Double; let expect: TiltExpect }
      struct TimeConstantCase: Decodable { let active: Bool; let expect: Double }
      struct ApproachCase: Decodable {
        let current: Double; let target: Double; let dt: Double; let tau: Double; let expect: Double
      }

      struct PoseExpect: Decodable {
        let opacity: Double; let rise: Double; let yawDegrees: Double; let pitchDegrees: Double
      }

      struct PoseCase: Decodable {
        let t: Double; let pointerYaw: Double; let pointerPitch: Double; let expect: PoseExpect
      }

      let motionVersion: Int
      let tolerance: Double
      let ease: [EaseCase]
      let entrance: [EntranceCase]
      let sway: [SwayCase]
      let pointerTarget: [PointerCase]
      let pointerTimeConstant: [TimeConstantCase]
      let approach: [ApproachCase]
      let pose: [PoseCase]
    }

    private func load() throws -> (VigMotion, Fixtures) {
      let motion = try VigMotion.load(from: .main)
      let url = try XCTUnwrap(
        Bundle(for: VigMotionTests.self).url(forResource: "vig-motion.fixtures", withExtension: "json"),
        "vig-motion.fixtures.json is missing from the test bundle"
      )
      let fixtures = try JSONDecoder().decode(Fixtures.self, from: Data(contentsOf: url))
      return (motion, fixtures)
    }

    func testFixturesMatchTheMotionVersion() throws {
      let (motion, fixtures) = try load()
      XCTAssertEqual(fixtures.motionVersion, motion.version)
    }

    func testEase() throws {
      let (_, f) = try load()
      XCTAssertFalse(f.ease.isEmpty)
      for c in f.ease {
        let easing = try XCTUnwrap(VigMotion.Easing(rawValue: c.easing))
        XCTAssertEqual(VigMotion.ease(easing, c.u), c.expect, accuracy: f.tolerance, "\(c.easing) at \(c.u)")
      }
    }

    func testEntrance() throws {
      let (m, f) = try load()
      XCTAssertFalse(f.entrance.isEmpty)
      for c in f.entrance {
        let e = m.entranceState(at: c.t)
        XCTAssertEqual(e.opacity, c.expect.opacity, accuracy: f.tolerance, "opacity at \(c.t)")
        XCTAssertEqual(e.rise, c.expect.rise, accuracy: f.tolerance, "rise at \(c.t)")
        XCTAssertEqual(e.yawDegrees, c.expect.yawDegrees, accuracy: f.tolerance, "yaw at \(c.t)")
      }
    }

    func testSway() throws {
      let (m, f) = try load()
      XCTAssertFalse(f.sway.isEmpty)
      for c in f.sway {
        XCTAssertEqual(m.sway(at: c.t), c.expect, accuracy: f.tolerance, "sway at \(c.t)")
      }
    }

    func testPointerTarget() throws {
      let (m, f) = try load()
      XCTAssertFalse(f.pointerTarget.isEmpty)
      for c in f.pointerTarget {
        let tilt = m.pointerTarget(x: c.x, y: c.y)
        XCTAssertEqual(tilt.yawDegrees, c.expect.yawDegrees, accuracy: f.tolerance, "yaw at (\(c.x), \(c.y))")
        XCTAssertEqual(tilt.pitchDegrees, c.expect.pitchDegrees, accuracy: f.tolerance, "pitch at (\(c.x), \(c.y))")
      }
    }

    func testPointerTimeConstant() throws {
      let (m, f) = try load()
      XCTAssertFalse(f.pointerTimeConstant.isEmpty)
      for c in f.pointerTimeConstant {
        XCTAssertEqual(m.pointerTimeConstant(active: c.active), c.expect, accuracy: f.tolerance)
      }
    }

    func testApproach() throws {
      let (_, f) = try load()
      XCTAssertFalse(f.approach.isEmpty)
      for c in f.approach {
        let v = VigMotion.approach(c.current, toward: c.target, deltaSeconds: c.dt, timeConstantSeconds: c.tau)
        XCTAssertEqual(v, c.expect, accuracy: f.tolerance, "\(c.current) → \(c.target) over \(c.dt) (τ \(c.tau))")
      }
    }

    func testPose() throws {
      let (m, f) = try load()
      XCTAssertFalse(f.pose.isEmpty)
      for c in f.pose {
        let p = m.pose(at: c.t, pointerYawDegrees: c.pointerYaw, pointerPitchDegrees: c.pointerPitch)
        XCTAssertEqual(p.opacity, c.expect.opacity, accuracy: f.tolerance, "opacity at \(c.t)")
        XCTAssertEqual(p.rise, c.expect.rise, accuracy: f.tolerance, "rise at \(c.t)")
        XCTAssertEqual(p.yawDegrees, c.expect.yawDegrees, accuracy: f.tolerance, "yaw at \(c.t)")
        XCTAssertEqual(p.pitchDegrees, c.expect.pitchDegrees, accuracy: f.tolerance, "pitch at \(c.t)")
      }
    }

    func testNeverTurnsPastTheLimits() throws {
      let (m, _) = try load()
      var t = 0.0
      while t < 30 {
        let p = m.pose(
          at: t,
          pointerYawDegrees: m.pointer.maxYawDegrees,
          pointerPitchDegrees: m.pointer.maxPitchDegrees * 2
        )
        XCTAssertLessThanOrEqual(abs(p.yawDegrees), m.limits.maxYawDegrees)
        XCTAssertLessThanOrEqual(abs(p.pitchDegrees), m.limits.maxPitchDegrees)
        t += 0.05
      }
    }
  }
#endif
